  <script>
    function toggleWhatsAppModal(show) {
      const waModal = document.getElementById('whatsappModal');
      if (waModal) {
        if (show) {
          waModal.classList.add('active');
          waModal.style.display = 'flex';
        } else {
          waModal.classList.remove('active');
          waModal.style.display = 'none';
        }
      }
    }
    function toggleEmailModal(show) {
      const emModal = document.getElementById('emailModal');
      if (emModal) {
        if (show) {
          emModal.classList.add('active');
          emModal.style.display = 'flex';
        } else {
          emModal.classList.remove('active');
          emModal.style.display = 'none';
        }
      }
    }
    document.addEventListener('DOMContentLoaded', function() {
      const waForm = document.getElementById('whatsappForm');
      const waModal = document.getElementById('whatsappModal');
      const emForm = document.getElementById('emailForm');
      const emModal = document.getElementById('emailModal');
      const hamburger = document.getElementById('hamburger');
      const mobileMenu = document.getElementById('mobile-menu');

      if (waModal) {
        waModal.addEventListener('click', function(e) {
          if (e.target === waModal) toggleWhatsAppModal(false);
        });
      }
      if (emModal) {
        emModal.addEventListener('click', function(e) {
          if (e.target === emModal) toggleEmailModal(false);
        });
      }
      if (waForm) {
        waForm.addEventListener('submit', function(e) {
          e.preventDefault();
          const name = document.getElementById('wa_name').value.trim();
          const phone = document.getElementById('wa_phone').value.trim();
          const email = document.getElementById('wa_email').value.trim();
          const msg = document.getElementById('wa_message').value.trim();
          let text = `*New WhatsApp Inquiry - Fan Air India*\n\n*Name:* ${name}\n*Phone:* ${phone}\n`;
          if (email) text += `*Email:* ${email}\n`;
          text += `*Requirement:* ${msg}`;
          window.open(`https://wa.me/919811347199?text=${encodeURIComponent(text)}`, '_blank');
          toggleWhatsAppModal(false);
          waForm.reset();
        });
      }
      if (emForm) {
        emForm.addEventListener('submit', function(e) {
          e.preventDefault();
          const name = document.getElementById('em_name').value.trim();
          const phone = document.getElementById('em_phone').value.trim();
          const email = document.getElementById('em_email').value.trim();
          const msg = document.getElementById('em_message').value.trim();
          let bodyText = `Name: ${name}\nPhone: ${phone}\nEmail: ${email}\n\nRequirement:\n${msg}`;
          window.location.href = `mailto:saurabh.joshi@fanair.in?subject=${encodeURIComponent('Product Inquiry - Fan Air India')}&body=${encodeURIComponent(bodyText)}`;
          toggleEmailModal(false);
          emForm.reset();
        });
      }
    });
  </script>
</body>
</html>
